	["Agregado a tu ruta"] = "Adicionado à sua rota",
	["Agregar a mi plan"] = "Adicionar ao meu plano",
	["Agregar a mi plan de misiones"] = "Adicionar ao meu plano de missões",
	["Agregar a mi ruta"] = "Adicionar à minha rota",
	["Agregar un tramo:"] = "Adicionar um trecho:",
	["Agrégale uno en la página Ruta."] = "Adicione um na página Rota.",
	["Agua y comida"] = "Água e comida",
	["Aguante"] = "Vigor",
	["Ahora"] = "Agora",
	["Ahora ganas la XP normal"] = "Agora você ganha a XP normal",
	["Ahora no"] = "Agora não",
	["Ahora no sale: Alfa busca cómo unirse a la manada."] = "Não está saindo agora: o Alfa procura como se juntar à matilha.",
	["Ahora no se puede"] = "Agora não é possível",
	["Ahora no se puede anunciar"] = "Não dá para anunciar agora",
	["Ahora no se pueden enviar mensajes (en una instancia o con una cuenta de prueba). %s"] = "Agora não é possível enviar mensagens (numa instância ou com uma conta de teste). %s",
	["Ahora usan: %s. Activa los pesos de %s para que Alfa compare el equipo como lo pide tu build."] = "Agora usam: %s. Ative os pesos de %s para o Alfa comparar o equipamento como sua build pede.",
	["Ahora va por el canal oculto de Alfa."] = "Agora vai pelo canal oculto do Alfa.",
	["Ahora va por tu hermandad: el canal oculto de Alfa no está disponible, así que solo te ven quienes comparten en tu hermandad."] = "Agora vai pela sua guilda: o canal oculto do Alfa não está disponível, então só quem compartilha na sua guilda vê você.",
	["Ahora: %d %% del nivel %d"] = "Agora: %d %% do nível %d",
	["Ahora: %s."] = "Agora: %s.",
	["Ahí no hay ninguna zona: pon el marcador sobre tierra."] = "Não há nenhuma zona aí: coloque o marcador em terra firme.",
	["Ahí no se puede poner la flecha."] = "Não dá para colocar a seta aí.",
	["Ahí nos organizamos para todo. Haz clic en el enlace y cópialo con Ctrl+C."] = "É lá que a gente se organiza para tudo. Clique no link e copie com Ctrl+C.",
	["Ajustar"] = "Ajustar",
	["Ajustar los avisos"] = "Ajustar os avisos",
	["Ajustes"] = "Opções",
	["Ajustes de Bolsas"] = "Opções de Bolsas",
	["Ajustes de mazmorras"] = "Opções de masmorras",
	["Ajustes del medidor"] = "Opções do medidor",
	["Al armar tus rutas, Alfa deja fuera las que piden élites."] = "Ao montar suas rotas, o Alfa deixa de fora as que pedem elites.",
	["Al comerciante"] = "Para o mercador",
	["Al comparar objetos, Alfa valora más lo que pide %s: lo de arriba en la lista de estadísticas."] = "Ao comparar itens, o Alfa valoriza mais o que %s pede: o que está no topo da lista de atributos.",
	["Al día"] = "Em dia",
	["Al elegir un build, las flechas de mejora de tus bolsas valoran lo que ese build necesita."] = "Ao escolher uma build, as setas de melhoria das suas bolsas valorizam o que essa build precisa.",
	["Al empezar aturde a quien lo despertó en el altar: es normal."] = "No começo ele atordoa quem o despertou no altar: é normal.",
	["Al enemigo le queda poca vida: remátalo."] = "O inimigo está com pouca vida: acabe com ele.",
	["Al final de la pelea se enfurece y pega más rápido: guarda curación para ese momento."] = "No fim da luta ele se enfurece e bate mais rápido: guarde cura para esse momento.",
	["Al final se enfurece: guarden su mejor daño para el final."] = "No fim ela se enfurece: guardem o melhor dano para o final.",
	["Al final, habla con el Discípulo de Naralex y protégelo mientras camina: así aparece el último jefe."] = "No final, fale com o Discípulo de Naralex e proteja-o enquanto ele caminha: é assim que aparece o último chefe.",
	["Al hablar con quien da una misión de tu ruta, se acepta sola. Mayús la deja para ti."] = "Ao falar com quem dá uma missão da sua rota, ela é aceita sozinha. Shift deixa para você.",
	["Al hablar con un banquero se abre el banco de Alfa, con depositar rápido. La primera visita de cada personaje muestra el del juego: así recibe su primera pestaña."] = "Ao falar com um bancário, abre o banco do Alfa, com depósito rápido. A primeira visita de cada personagem mostra o do jogo: assim ele recebe a primeira aba.",
	["Al llegar a una ciudad o posada. También repite la nota de entrenar de la guía cuando su ventana está oculta."] = "Ao chegar a uma cidade ou estalagem. Também repete a nota de treinamento do guia quando a janela dele está escondida.",
	["Al morir aparecen cuatro abisarios que caminan juntos por el patio: prepárense para pelear con varios."] = "Quando ele morre, aparecem quatro emissários do caos que andam juntos pelo pátio: preparem-se para enfrentar vários.",
	["Al morir llegan muchos aprendices: prepárense para muchos enemigos a la vez."] = "Quando ele morre, chegam muitos aprendizes: preparem-se para muitos inimigos de uma vez.",
	["Al objetivo le queda poca vida: Ejecutar lo remata usando tu ira."] = "O alvo está com pouca vida: Executar acaba com ele usando sua raiva.",
	["Al objetivo le queda poca vida: el martillo lo remata a distancia."] = "O alvo está com pouca vida: o martelo acaba com ele à distância.",
	["Al pasar el ratón por un objeto: «Tienes 12 (Toxic: 7 en bolsas, Alt: 5 en banco)», con todos tus personajes."] = "Ao passar o mouse sobre um item: “Você tem 12 (Toxic: 7 nas bolsas, Alt: 5 no banco)”, somando todos os seus personagens.",
	["Al pasar el ratón sobre un objeto: su precio en la subasta, lo que paga el comerciante y qué te conviene."] = "Ao passar o mouse sobre um item: o preço no leilão, quanto o mercador paga e o que vale mais a pena.",
	["Al recibir daño suelta pedazos más pequeños: mátenlos con ataques en área."] = "Ao receber dano, ele solta pedaços menores: matem-nos com ataques em área.",
	["Al subir de nivel (y al entrar, si te quedan puntos), un aviso dice qué talento poner, con el botón para aplicarlo."] = "Ao subir de nível (e ao entrar, se sobrarem pontos), um aviso diz qual talento pegar, com o botão para aplicá-lo.",
	["Al subir de nivel te muestra qué aprender y cuánto cuesta."] = "Ao subir de nível, mostra o que aprender e quanto custa.",
	["Al subir de nivel, un aviso dice qué aprender, cuánto cuesta y con qué entrenador, con el botón Llévame."] = "Ao subir de nível, um aviso diz o que aprender, quanto custa e com qual instrutor, com o botão Me leve.",
	["Alejar"] = "Afastar",
	["Alejar más la cámara"] = "Afastar mais a câmera",
	["Alertas"] = "Alertas",
	["Alfa"] = "Alfa",
	["Alfa (el estilo propio, por omisión), Clásico WoW (marcos y letras del juego) o Cristal (transparente, con el acento que elijas). El modo compacto y tus colores funcionan en los tres."] = "Alfa (o estilo próprio, padrão), WoW Clássico (quadros e fontes do jogo) ou Cristal (transparente, com a cor de destaque que você escolher). O modo compacto e suas cores funcionam nos três.",
	["Alfa 1.0 ya está aquí"] = "O Alfa 1.0 chegou",
	["Alfa abre sin sonido. Lo enciendes cuando quieras en Ajustes > Estilo y sonido."] = "O Alfa abre sem som. Ative quando quiser em Opções > Estilo e som.",
	["Alfa arma la ruta más corta para cobrarlas, junta por PNJ. La flecha usa vuelos y tu piedra de hogar cuando conviene, y te avisa si una entrega queda lejos."] = "O Alfa monta a rota mais curta para cobrá-las, agrupadas por PNJ. A seta usa voos e sua Pedra de Regresso quando vale a pena, e avisa se uma entrega fica longe.",
	["Alfa borrará lo que guardó de %s: sus bolsas, su banco y su equipo. Si vuelves a jugar con él, se guarda de nuevo."] = "O Alfa vai apagar o que guardou de %s: bolsas, banco e equipamento. Se você voltar a jogar com ele, tudo é guardado de novo.",
	["Alfa elige las misiones que más XP dan cerca de ti, en tres tandas."] = "O Alfa escolhe as missões que mais dão XP perto de você, em três levas.",
	["Alfa elige todo: misiones ordenadas por XP por distancia y tus misiones de clase."] = "O Alfa escolhe tudo: missões ordenadas por XP por distância e suas missões de classe.",
	["Alfa está armando tu ruta..."] = "O Alfa está montando sua rota...",
	["Alfa está eligiendo..."] = "O Alfa está escolhendo...",
	["Alfa está leyendo tu clase"] = "O Alfa está lendo sua classe",
	["Alfa está oculto: clic para mostrarlo y abrir su ventana"] = "O Alfa está escondido: clique para mostrá-lo e abrir a janela dele",
	["Alfa lee el medidor oficial del juego. Enciéndelo y aquí verás el daño de tu grupo; su ventana puedes ocultarla en el Modo de edición."] = "O Alfa lê o medidor oficial do jogo. Ative e aqui você verá o dano do seu grupo; a janela dele pode ser ocultada no Modo de Edição.",
	["Alfa los cambia por el rango nuevo sin moverlos de lugar."] = "O Alfa troca pelo grau novo sem mudá-los de lugar.",
	["Alfa mide los caminos (vuelos y piedra de hogar): tarda unos segundos."] = "O Alfa mede os caminhos (voos e Pedra de Regresso): leva uns segundos.",
	["Alfa no pudo armar el camino a %s. Míralo en la Enciclopedia."] = "O Alfa não conseguiu montar o caminho até %s. Veja na Enciclopédia.",
	["Alfa no tiene datos de esto todavía."] = "O Alfa ainda não tem dados disso.",
	["Alfa no toma misiones que no sirven a tu ruta, ni las entrega solas. Lo respeta también «todas las misiones» de Comodidades."] = "O Alfa não pega missões que não servem para sua rota, nem as entrega sozinho. A opção “Todas as missões” de Comodidades também respeita isso.",
	["Alfa ordena las paradas para que no camines de más. Tarda unos segundos y no traba el juego."] = "O Alfa ordena as paradas para você não andar à toa. Leva uns segundos e não trava o jogo.",
	["Alfa revisa su base de objetos sin trabar el juego. Tarda unos segundos la primera vez."] = "O Alfa revisa a base de itens sem travar o jogo. Leva uns segundos na primeira vez.",
	["Alfa revisa su base de objetos, se queda con lo que tu clase puede usar cerca de tu nivel y lo compara con lo que llevas, con los pesos de tu build."] = "O Alfa revisa a base de itens, fica com o que sua classe pode usar perto do seu nível e compara com o que você usa, com os pesos da sua build.",
	["Alfa se está uniendo al canal oculto de La Jauría. En unos segundos ves a quien comparte."] = "O Alfa está entrando no canal oculto de La Jauría. Em alguns segundos você vê quem compartilha.",
	["Alfa tampoco tiene todavía una prioridad para tu clase con lo que sabes. Los avisos de reacción y el medidor sí funcionan."] = "O Alfa também ainda não tem uma prioridade para sua classe com o que você sabe. Os avisos de reação e o medidor funcionam.",
	["Alfa te avisa aquí de lo importante: equipo por reparar, bolsas llenas, habilidades nuevas, tu buff y tu descanso."] = "O Alfa avisa aqui o que importa: equipamento para reparar, bolsas cheias, habilidades novas, seu buff e seu descanso.",
	["Alfa te avisa del equipo gastado, las bolsas llenas, lo que puedes entrenar, tu buff y tu descanso. Aquí eliges cuáles y cuándo."] = "O Alfa avisa sobre equipamento desgastado, bolsas cheias, o que você pode treinar, seu buff e seu descanso. Aqui você escolhe quais e quando.",
	["Alfa te lleva paso a paso, con la flecha y la ruta en el mapa. Elige la de tu zona y tu nivel."] = "O Alfa leva você passo a passo, com a seta e a rota no mapa. Escolha o da sua zona e do seu nível.",
	["Alfa todavía no tiene builds para tu clase"] = "O Alfa ainda não tem builds para sua classe",
	["Alfa vuelve a elegir desde donde estás ahora (las misiones fijas se quedan)."] = "O Alfa escolhe de novo a partir de onde você está agora (as missões fixadas ficam).",
	["Alfa · Top %d de %s (%s%s)"] = "Alfa · Top %d de %s (%s%s)",
	["Alfa, Clásico WoW o Cristal, la flecha del lobo y el aullido."] = "Alfa, WoW Clássico ou Cristal, a seta do lobo e o uivo.",
	["Alfa: agregar a mi plan de misiones"] = "Alfa: adicionar ao meu plano de missões",
	["Alfa: capas del mapa"] = "Alfa: camadas do mapa",
	["Alfa: cerrar mis misiones"] = "Alfa: fechar minhas missões",
	["Alfa: quitar de mi plan de misiones"] = "Alfa: remover do meu plano de missões",
	["Alfa_Codex está apagado en la lista de addons."] = "O Alfa_Codex está desativado na lista de addons.",
	["Alianza"] = "Aliança",
	["Alquimia"] = "Alquimia",
	["Alt"] = "Alt",
	["Alt+clic en un objeto abre su ficha"] = "Alt+clique num item abre a ficha dele",
	["Alto"] = "Altura",
	["Amenaza"] = "Ameaça",
	["Ancho"] = "Largura",
	["Anillos"] = "Anéis",
	["Animación anterior"] = "Animação anterior",
	["Animación siguiente"] = "Próxima animação",
	["Anterior"] = "Anterior",
	["Antes de entrar"] = "Antes de entrar",
	["Antes de salir de caza, unas preguntas rápidas: cómo quieres que se vea Alfa, qué misiones toma por ti y si quieres el aullido."] = "Antes de sair para a caça, umas perguntas rápidas: como você quer ver o Alfa, quais missões ele pega por você e se você quer o uivo.",
	["Antes de salir de caza, unas preguntas rápidas: cómo quieres que se vea Alfa, qué misiones toma por ti, si compartes tu ubicación con La Jauría y si quieres el aullido."] = "Antes de sair para a caça, umas perguntas rápidas: como você quer ver o Alfa, quais missões ele pega por você, se você compartilha sua localização com La Jauría e se você quer o uivo.",
	["Antes hay que hacer otra misión"] = "Antes é preciso fazer outra missão",
	["Antes necesitas"] = "Antes você precisa",
	["Antes necesitas otra misión"] = "Precisa de outra missão antes",
	["Antes: %s"] = "Antes: %s",
	["Antes: %s."] = "Antes: %s.",
	["Anunciar"] = "Anunciar",
	["Anunciar en el chat"] = "Anunciar no chat",
	["Anunciar en el grupo"] = "Anunciar no grupo",
	["Apaga la música y el ambiente y sube los efectos para que oigas cuando pica, aunque el juego esté en segundo plano. Al terminar, todo vuelve a como estaba."] = "Desliga a música e o ambiente e aumenta os efeitos para você ouvir quando o peixe morder, mesmo com o jogo em segundo plano. Ao terminar, tudo volta a ser como era.",
	["Apagada"] = "Desativada",
	["Apagadas"] = "Desativadas",
	["Apagado"] = "Desativado",
	["Apagado, solo las acepta y la entrega la haces tú."] = "Desativado, só aceita as missões e quem entrega é você.",
	["Apagados"] = "Desativados",
	["Aparece al final del evento del Discípulo de Naralex: protege al druida mientras camina."] = "Aparece no fim do evento do Discípulo de Naralex: proteja o druida enquanto ele caminha.",
	["Aparece al tocar el gong por tercera vez, después de dos oleadas de arañas."] = "Aparece ao tocar o gongo pela terceira vez, depois de duas ondas de aranhas.",
	["Aparece con una misión de la Horda (un objeto en el agua). Lanza escarcha."] = "Aparece com uma missão da Horda (um objeto na água). Lança gelo.",
	["Aparece en el evento de la explosivista: protégela mientras llegan oleadas de troggs."] = "Aparece no evento da explosivista: proteja-a enquanto chegam ondas de troggs.",
	["Aparecen marcos de ejemplo: arrástralos a donde los quieras y ajusta su tamaño. Así se verá tu grupo."] = "Aparecem quadros de exemplo: arraste-os para onde quiser e ajuste o tamanho. Assim seu grupo vai aparecer.",
	["Aplaudir"] = "Aplaudir",
	["Aplicar"] = "Aplicar",
	["Aplicar %d puntos"] = "Aplicar %d pontos",
	["Aprende Pesca"] = "Aprenda Pesca",
	["Aprende Pesca con un instructor de pesca (hay en las capitales) y compra una caña. Luego vuelve aquí."] = "Aprenda Pesca com um instrutor de pesca (há um em cada capital) e compre uma vara de pescar. Depois volte aqui.",
	["Aprender de tus búsquedas"] = "Aprender com suas buscas",
	["Aprendiste un hechizo que le queda mejor a tus clics:"] = "Você aprendeu um feitiço que combina melhor com seus cliques:",
	["Apréndelos con el entrenador de tu clase, en cualquier capital."] = "Aprenda com o instrutor da sua classe, em qualquer capital.",
	["Apágalo si no quieres que Alfa toque tu tecla ni tus ajustes al pescar."] = "Desative se não quiser que o Alfa mexa na sua tecla nem nas suas opções ao pescar.",
	["Aquí aparecerán los demás módulos de Alfa (bolsas, rutas, mundo y más) en cuanto estén instalados."] = "Aqui vão aparecer os outros módulos do Alfa (bolsas, rotas, mundo e mais) assim que forem instalados.",
	["Aquí el juego no da tu posición (por ejemplo, dentro de una mazmorra)."] = "Aqui o jogo não informa sua posição (por exemplo, dentro de uma masmorra).",
	["Aquí el juego no deja compartir nada. Al salir, tu rastro vuelve a salir solo."] = "Aqui o jogo não deixa compartilhar nada. Ao sair, seu rastro volta a sair sozinho.",
	["Aquí no hay nodos que recolectar"] = "Aqui não há pontos para coletar",
	["Aquí sale por qué se activó la habilidad."] = "Aqui aparece por que a habilidade foi ativada.",
	["Aquí ves todo lo que hay que saber, con qué hacer después."] = "Aqui você vê tudo o que precisa saber e o que fazer depois.",
	["Arañazo: sangrado con el tiempo."] = "Rasgar: sangramento ao longo do tempo.",
	["Arcano"] = "Arcano",
	["Arcano para subir"] = "Arcano para subir de nível",
	["Arco"] = "Arco",
	["Arena"] = "Areia",
	["Arma"] = "Arma",
	["Arma con tu ruta lo que necesitas para poder tomarla: el nivel o las misiones de antes."] = "Monta com a sua rota o que você precisa para poder pegá-la: o nível ou as missões anteriores.",
	["Arma de asta"] = "Arma de Haste",
	["Arma de dos manos"] = "Arma de duas mãos",
	["Arma de dos manos, sellos y juicios: el paladín que mejor sube en solitario."] = "Arma de duas mãos, selos e julgamentos: o paladino que melhor sobe de nível sozinho.",
	["Arma de fuego"] = "Arma de Fogo",
	["Arma de puño"] = "Arma de Punho",
	["Arma el plan para cerrar las misiones de tu registro y te lleva a cada una."] = "Monta o plano para fechar as missões do seu registro e leva você a cada uma.",
	["Arma una ruta de %s en %s"] = "Monte uma rota de %s em %s",
	["Arma y escudo"] = "Arma e escudo",
	["Armadura"] = "Armadura",
	["Armaduras"] = "Armaduras",
	["Armando"] = "Montando",
	["Armando tu plan de misiones..."] = "Montando seu plano de missões...",
	["Armar la ruta"] = "Montar a rota",
	["Armar lo que falta"] = "Montar o que falta",
	["Armar mi plan"] = "Montar meu plano",
	["Armas"] = "Armas",
	["Armas a dos manos"] = "Armas de duas mãos",
	["Armas a muerte"] = "Armas com tudo",
	["Armas contra jugadores"] = "Armas contra jogadores",
	["Armas para grupo"] = "Armas para grupo",
	["Armas pensado para mazmorras: mucho daño en varios enemigos con Golpes de barrido, Golpe mortal para los jefes y más precisión para no fallar."] = "Armas pensado para masmorras: muito dano em vários inimigos com Sweeping Strikes, Golpe Mortal para os chefes e mais precisão para não errar.",
	["Armas pensando primero en no morir: paras más golpes, frenas a los que huyen y terminas con un poco de Protección para recibir menos daño."] = "Armas pensando primeiro em não morrer: você apara mais golpes, segura quem foge e termina com um pouco de Proteção para receber menos dano.",
	["Armas seguro"] = "Armas seguro",
	["Armas, armaduras, materiales, recetas y monturas: quién los suelta y quién los vende."] = "Armas, armaduras, materiais, receitas e montarias: quem deixa cair e quem vende.",
	["Arrastra cada marco de combate adonde te acomode. Cuando termines, fíjalos para que no estorben."] = "Arraste cada quadro de combate para onde for melhor. Quando terminar, trave-os para não atrapalharem.",
	["Arrastra otra bolsa aquí para cambiarla."] = "Arraste outra bolsa aqui para trocá-la.",
	["Arrastra para mover tus marcos. Cambia el tamaño y las columnas en la página Curación."] = "Arraste para mover seus quadros. Mude o tamanho e as colunas na página Cura.",
	["Arrastra para mover tus marcos. Haz clic (con o sin Mayús, Ctrl o Alt) para ver qué lanzaría."] = "Arraste para mover seus quadros. Clique (com ou sem Shift, Ctrl ou Alt) para ver o que lançaria.",
	["Arrastra una bolsa aquí para ponerla."] = "Arraste uma bolsa aqui para equipá-la.",
	["Arriba de la ventana, cada bolsa equipada con su espacio: pasa el ratón para resaltar lo que lleva y arrastra otra bolsa para cambiarla."] = "No alto da janela, cada bolsa equipada com seu espaço: passe o mouse para destacar o que ela leva e arraste outra bolsa para trocá-la.",
	["Arriba, lo que Alfa recomienda. Un clic y empiezas."] = "No alto, o que o Alfa recomenda. Um clique e você começa.",
	["Arriesgado"] = "Arriscado",
	["Arrodillarse"] = "Ajoelhar",
	["Arrojadiza"] = "Arremesso",
	["Arrástralo para moverlo"] = "Arraste para mover",
	["Artefacto"] = "Artefato",
	["Artesanía y comercio"] = "Artesanato e mercadorias",
	["Asesinato"] = "Assassinato",
	["Asesinato para subir"] = "Assassinato para subir de nível",
	["Asistente"] = "Assistente",
	["Aspecto"] = "Aspecto",
	["Asusta a todos los que están cerca: si te asusta, intenta no correr hacia otras celdas."] = "Ele amedronta todos que estão perto: se você for amedrontado, tente não correr para outras celas.",
	["Asusta y duerme a los jugadores: si te asusta, intenta no correr hacia más enemigos."] = "Ele amedronta e põe os jogadores para dormir: se você for amedrontado, tente não correr para mais inimigos.",
	["Así sabes qué hace cada clic antes de tu próxima pelea."] = "Assim você sabe o que cada clique faz antes da sua próxima luta.",
	["Así se ven tus avisos"] = "Assim ficam seus avisos",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo, en Marcos. Pulsa Listo cuando termines."] = "É assim que seus quadros vão aparecer. Arraste-os para movê-los e mude o tamanho abaixo, em Quadros. Aperte Pronto quando terminar.",
	["Así se verán tus marcos. Arrástralos para moverlos y cambia su tamaño abajo. Pulsa Listo cuando termines."] = "Assim vão ficar seus quadros. Arraste para movê-los e mude o tamanho abaixo. Clique em Pronto quando terminar.",
