	["Con el entrenador más cercano en tu camino."] = "Com o instrutor mais próximo no seu caminho.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. Pulsa el botón y luego la tecla que quieras."] = "Com ela você lança a vara e, quando o peixe morde, recolhe. Aperte o botão e depois a tecla que quiser.",
	["Con ella lanzas la caña y, cuando pica, recoges el pez. También está en el menú de atajos del juego, en Alfa."] = "Com ela você lança a vara e, quando o peixe morde, recolhe. Também está no menu de atalhos do jogo, em Alfa.",
	["Con la caña en el agua"] = "Com a linha na água",
	["Con la interfaz de mando el mapa del juego se abre con su tecla."] = "Com a interface para controle, o mapa do jogo abre com a tecla dele.",
	["Con la interfaz para mando, Alfa deja las bolsas del juego. Igual puedes abrir la ventana de Alfa desde aquí."] = "Com a interface para controle, o Alfa deixa as bolsas do jogo. Mesmo assim, você pode abrir a janela do Alfa por aqui.",
	["Con las de Alfa ves todo en una ventana: tres vistas, búsqueda, la barra de tus bolsas y qué vender cuando se llenan."] = "Com as do Alfa você vê tudo numa janela: três visões, busca, a barra das suas bolsas e o que vender quando elas enchem.",
	["Con mando, se quedan las bolsas del juego"] = "Com controle, ficam as bolsas do jogo",
	["Con o sin Mayús, Ctrl o Alt. No lanza nada: aquí ves qué lanzaría sobre tu compañero."] = "Com ou sem Shift, Ctrl ou Alt. Não lança nada: aqui você vê o que lançaria no seu companheiro.",
	["Con poca vida llama a dos ayudantes: si a él le queda poco, terminen con él; si no, maten a los ayudantes."] = "Com pouca vida ele chama dois ajudantes: se ele estiver quase morto, acabem com ele; se não, matem os ajudantes.",
	["Con poca vida se convierte en serpiente y pega más fuerte: guarda tus mejores ataques para ese momento."] = "Com pouca vida ele vira serpente e bate mais forte: guarde seus melhores ataques para esse momento.",
	["Con reputación %s"] = "Com reputação %s",
	["Con sonido"] = "Com som",
	["Con tu build, Alfa sabe qué estadísticas te sirven y qué equipo buscar."] = "Com a sua build, o Alfa sabe quais atributos servem para você e que equipamento procurar.",
	["Con tu punto libre se compra 1 rango de %s:"] = "Com seu ponto livre, você compra 1 nível de %s:",
	["Con tus %d puntos libres se compran %d rangos de %s:"] = "Com seus %d pontos livres, são comprados %d níveis de %s:",
	["Con un enemigo elegido, antes de empezar la pelea, y transparente para que no estorbe."] = "Com um inimigo como alvo, antes de começar a luta, e transparente para não atrapalhar.",
	["Congela a los que están cerca: si peleas de lejos, aléjate."] = "Ele congela quem está perto: se você luta à distância, fique afastado.",
	["Congela al monstruo con Nova de escarcha y aléjate antes de seguir lanzando."] = "Congele o monstro com Nova Congelante e afaste-se antes de continuar lançando.",
	["Congela en el lugar y lanza rayos: si peleas de lejos, sepárate del grupo."] = "Ela prende no lugar e lança raios: se você luta à distância, afaste-se do grupo.",
	["Congelas y frenas a los monstruos para que nunca te alcancen: el mago más seguro para subir."] = "Você congela e deixa os monstros lentos para que nunca alcancem você: o mago mais seguro para subir de nível.",
