	["Enciende los cambios de abajo en el probador (Ctrl + clic en un objeto)."] = "Ativa as mudanças abaixo no provador (Ctrl + clique num item).",
	["Enciende los cambios de abajo; cada uno se puede apagar por separado. Algunos addons acomodan sus botones al cuadrado después de /reload."] = "Ativa as mudanças abaixo; cada uma pode ser desativada separadamente. Alguns addons ajeitam seus botões ao quadrado depois de /reload.",
