	["Haz doble clic derecho en el mundo para lanzar la caña, sin usar la tecla. Nunca en combate ni en vuelo."] = "Dê um clique duplo direito no mundo para lançar a linha, sem usar a tecla. Nunca em combate nem em voo.",
	["Haz doble clic derecho en el mundo para lanzar. Cuando pique, haz clic derecho sobre el corcho para recoger."] = "Dê um clique duplo direito no mundo para lançar. Quando o peixe morder, clique com o botão direito na boia para recolher.",
