	["Hechizos de sombras que hacen daño con el tiempo: el sacerdote que mejor sube en solitario, casi sin descansar."] = "Feitiços de sombra que causam dano ao longo do tempo: o sacerdote que melhor sobe de nível sozinho, quase sem descansar.",
	["Hechizos desde lejos y raíces para que el monstruo no te alcance. Al final llega la forma de lechúcico."] = "Feitiços de longe e raízes para o monstro não alcançar você. No final chega a Moonkin Form.",
