	["Herrería fabrica armas y armadura de placas muy buenas para tu nivel, y Minería te da el material gratis."] = "A Ferraria fabrica armas e armaduras de placas muito boas para o seu nível, e a Mineração dá o material de graça.",
	["Herrería fabrica escudos y piezas resistentes."] = "A Ferraria fabrica escudos e peças resistentes.",
