	["Igual que lo tuyo"] = "Igual ao seu",
	["Igual que los otros señores: lanza rayos y se cura. Interrumpe su curación."] = "Igual aos outros senhores: lança raios e se cura. Interrompa a cura dele.",
	["Importa una cadena de escala de estadísticas y usa, renombra, exporta o borra las escalas que tienes."] = "Importe um código de escala de atributos e use, renomeie, exporte ou apague as escalas que você tem.",
