	["Ingeniería"] = "Engenharia",
	["Ingeniería da aturdimientos y trucos que ganan duelos; Minería da el material."] = "A Engenharia dá atordoamentos e truques que ganham duelos; a Mineração dá o material.",
	["Ingeniería da granadas y redes para controlar al rival; Minería da el material."] = "A Engenharia dá granadas e redes para controlar o rival; a Mineração dá o material.",
	["Ingeniería da granadas, redes y bombas que deciden peleas contra jugadores; Minería da el material."] = "A Engenharia dá granadas, redes e bombas que decidem lutas contra jogadores; a Mineração dá o material.",
	["Ingeniería te salva con trucos de escape; Sastrería hace tu ropa."] = "A Engenharia salva você com truques de fuga; a Alfaiataria faz suas roupas.",
	["Inicio"] = "Início",
