	["Intentar ahora"] = "Tentar agora",
	["Intentar otra vez"] = "Tentar de novo",
	["Interceptar más seguido: el rival no se escapa."] = "Interceptar com mais frequência: o rival não escapa.",
	["Interrumpes hechizos y los silencias."] = "Você interrompe feitiços e os silencia.",
