	["Invitar"] = "Convidar",
	["Invitar al grupo"] = "Convidar para o grupo",
	["Invitar, comerciar, susurrar…"] = "Convidar, negociar, sussurrar…",
	["Invitaste a %s a tu grupo."] = "Você convidou %s para o seu grupo.",
	["Invoca un espíritu de jabalí: mátenlo o que alguien lo tanquee."] = "Ele evoca um espírito de javali: matem-no ou alguém o tanqueie.",
	["Invócalo antes de pelear."] = "Invoque-o antes de lutar.",
	["Ir"] = "Ir",
	["Ir al mapa del juego"] = "Ir para o mapa do jogo",
	["Ira al romper un miedo: los rivales te asustan mucho."] = "Raiva ao quebrar um medo: os rivais amedrontam você muito.",
	["Ira aunque el rival huya o te frene."] = "Raiva mesmo que o rival fuja ou deixe você lento.",
	["Ira constante en peleas largas contra jefes."] = "Raiva constante em lutas longas contra chefes.",
	["Ira constante."] = "Raiva constante.",
	["Ira constante: nunca te quedas sin poder usar habilidades."] = "Raiva constante: você nunca fica sem poder usar habilidades.",
	["Ira gratis cada pocos segundos, aunque nadie te pegue."] = "Raiva grátis a cada poucos segundos, mesmo que ninguém bata em você.",
	["Izquierdo"] = "Esquerdo",
	["JcJ"] = "JxJ",
	["Jefe"] = "Chefe",
	["Jefe %d por descubrir"] = "Chefe %d a descobrir",
	["Jefe final"] = "Chefe final",
	["Jefes"] = "Chefes",
	["Jefes vencidos"] = "Chefes derrotados",
	["Jefes vencidos, mazmorras hechas y botín anotado de este personaje. No toca tus ajustes."] = "Chefes derrotados, masmorras feitas e saque anotado deste personagem. Suas opções não mudam.",
	["Jefes, botín y la entrada de cada mazmorra y banda."] = "Chefes, saque e a entrada de cada masmorra e raide.",
	["Juega con cada personaje una vez y Alfa recordará sus bolsas y su banco."] = "Jogue com cada personagem uma vez e o Alfa vai lembrar das bolsas e do banco dele.",
	["Juega siempre en actitud defensiva con escudo."] = "Jogue sempre na Postura Defensiva com escudo.",
	["Junta %d de %s"] = "Junte %d de %s",
	["Junta dos monstruos y usa Golpes de barrido: así subes más rápido."] = "Junte dois monstros e use Sweeping Strikes: assim você sobe mais rápido.",
	["Junta dos o tres monstruos, usa Atronar y Revancha: subes seguro y sin descansar."] = "Junte dois ou três monstros, use Trovoada e Revanche: você sobe com segurança e sem descansar.",
	["Junta los montones y acomoda tus objetos con un clic."] = "Junta as pilhas e organiza seus itens com um clique.",
	["Junta los montones y acomoda tus objetos. No funciona en combate."] = "Junta as pilhas e organiza seus itens. Não funciona em combate.",
	["Junta materiales de tu profesión donde más hay."] = "Junte materiais da sua profissão onde há mais.",
	["Junta materiales de tu profesión, con unas misiones de XP en medio."] = "Junte materiais da sua profissão, com algumas missões de XP no meio.",
	["Junta varios monstruos: tus golpes sagrados alcanzan a todos."] = "Junte vários monstros: seus golpes sagrados alcançam todos.",
	["Juntando todo lo del juego. Es solo la primera vez que la abres."] = "Juntando tudo do jogo. Só na primeira vez que você abre.",
	["Juntar los materiales de mi profesión"] = "Juntar os materiais da minha profissão",
	["Juntar materiales para vender"] = "Juntar materiais para vender",
	["Juntar nodos cercanos al alejar"] = "Juntar pontos próximos ao afastar",
	["Junto a la lupa del mapa del juego: las capas, el modo limpio y «Mapa de Alfa» para cambiar al de Alfa."] = "Ao lado da lupa do mapa do jogo: as camadas, o modo limpo e “Mapa do Alfa” para mudar para o do Alfa.",
	["La B, Mayús+B, la tecla de cada bolsa y los comerciantes abren la ventana de Alfa. Apágalo para volver a las del juego."] = "B, Shift+B, a tecla de cada bolsa e os mercadores abrem a janela do Alfa. Desative para voltar às do jogo.",
	["La Jauría"] = "La Jauría",
	["La Jauría en el mapa"] = "La Jauría no mapa",
	["La Jauría son todos los que usan Alfa. Si aceptas, quienes también comparten te ven en su mapa y te pueden seguir con la flecha, y tú a ellos. Se envía tu zona, tu posición, tu nivel y tu clase, nunca dentro de mazmorras. Tu grupo se ve siempre. Lo cambias cuando quieras en La Jauría."] = "La Jauría são todos os que usam o Alfa. Se você aceitar, quem também compartilha vê você no mapa e pode seguir você com a seta, e você a eles. São enviados sua zona, sua posição, seu nível e sua classe, nunca dentro de masmorras. Seu grupo sempre aparece. Mude quando quiser em La Jauría.",
	["La Jauría son todos los que usan Alfa. Si compartes tu ubicación, te ven en su mapa y tú a ellos: quién anda cerca, dónde y, con un clic, la flecha te lleva. Tu grupo se ve siempre, compartas o no."] = "La Jauría são todos os que usam o Alfa. Se você compartilhar sua localização, eles veem você no mapa e você a eles: quem está perto, onde e, com um clique, a seta leva você. Seu grupo sempre aparece, compartilhando ou não.",
	["La Jauría te ve"] = "La Jauría vê você",
	["La Jauría: estado"] = "La Jauría: estado",
	["La Jauría: tu manada en el mapa, Seguir y el clan (/alfa manada ayuda)"] = "La Jauría: sua matilha no mapa, Seguir e o clã (/alfa manada ayuda)",
	["La Jauría: tus comandos"] = "La Jauría: seus comandos",
	["La ayuda de rotación está apagada"] = "A ajuda de rotação está desativada",
	["La barra de vida con el color de la clase de cada uno. Apagado: barra verde y el nombre con su color."] = "A barra de vida com a cor da classe de cada um. Desativado: barra verde e o nome com a cor dele.",
	["La base incluida trae %s lugares en %d zonas. Tú descubriste %s."] = "A base incluída traz %s lugares em %d zonas. Você descobriu %s.",
	["La bienvenida con las novedades de esta versión."] = "As boas-vindas com as novidades desta versão.",
	["La búsqueda de lugares cercanos no está disponible."] = "A busca de lugares próximos não está disponível.",
	["La cadena no trae talentos válidos."] = "O código não traz talentos válidos.",
	["La cura de ese clic pasa al botón central."] = "A cura desse clique passa para o botão do meio.",
	["La derecha"] = "A direita",
	["La empieza un objeto"] = "Começa com um item",
	["La enciclopedia de La Jauría"] = "A enciclopédia de La Jauría",
	["La enciclopedia no puede abrir todavía"] = "A enciclopédia ainda não pode abrir",
	["La entrada de cada mazmorra en el minimapa, en verde las que ya hiciste. El mapa del mundo ya las marca con «Entradas de mazmorras»."] = "A entrada de cada masmorra no minimapa, em verde as que você já fez. O mapa-múndi já as marca com “Entradas de masmorras”.",
	["La flecha se mueve con su rastro y se detiene al llegar."] = "A seta se move com o rastro e para quando você chega.",
	["La flecha sigue caminos por el suelo alrededor de acantilados, agua y muros, con los mapas para caminar de Alfa. Apagado: apunta directo a cada parada."] = "A seta segue caminhos pelo chão contornando penhascos, água e muros, nos mapas de caminhada do Alfa. Desativado: aponta direto para cada parada.",
	["La flecha sigue en el paso de ahora."] = "A seta continua no passo atual.",
	["La flecha te lleva a %s."] = "A seta leva você até %s.",
	["La flecha te lleva aquí."] = "A seta leva você até aqui.",
	["La flecha te lleva de un lugar al siguiente."] = "A seta leva você de um lugar para o próximo.",
	["La flecha tomó otro destino: dejaste de seguir a %s."] = "A seta mudou de destino: você parou de seguir %s.",
	["La flecha usa vuelos y tu piedra de hogar cuando conviene."] = "A seta usa voos e sua Pedra de Regresso quando vale a pena.",
	["La flecha ya no sigue tu ruta de farmeo."] = "A seta não segue mais a sua rota de farm.",
	["La guía en el minimapa"] = "O guia no minimapa",
	["La guía que mejor te queda por tu nivel y donde estás."] = "O guia que mais combina com você pelo seu nível e onde você está.",
	["La guía que sigues, tu paso de ahora y todo lo de las guías a un clic."] = "O guia que você segue, seu passo atual e tudo sobre guias a um clique.",
	["La guía te lleva a entrenar en %d pasos."] = "O guia leva você para treinar em %d passos.",
	["La guía te lleva a quien recibe cada una."] = "O guia leva você a quem recebe cada uma.",
	["La haces de paso: abre %s."] = "Você faz de passagem: abre %s.",
	["La haré"] = "Vou fazer",
	["La letra del aspecto (Inter en el de Alfa, Fira Sans en Halo, la del juego en los demás) o la que elijas."] = "A fonte do tema (Inter no do Alfa, Fira Sans no Halo, a do jogo nos outros) ou a que você escolher.",
	["La lista está apagada: enciende «Tu lista de sonidos» en Comodidades (/alfa comodidades)."] = "A lista está desativada: ative “Sua lista de sons” em Comodidades (/alfa comodidades).",
	["La lista por nivel y tu progreso."] = "A lista por nível e seu progresso.",
	["La línea de tiempo de Blizzard dice qué ataque viene y cuándo, y los mensajes grandes, lo peligroso. Alfa no inventa avisos: los prendes y ajustas en Ajustes."] = "A linha do tempo da Blizzard diz qual ataque vem e quando, e as mensagens grandes, o que é perigoso. O Alfa não inventa avisos: você ativa e ajusta em Opções.",
	["La línea del camino también en el minimapa."] = "A linha do caminho também no minimapa.",
	["La manada a la vista"] = "A matilha à vista",
	["La manada aúlla contigo."] = "A matilha uiva com você.",
	["La manada te saluda al abrir Alfa por primera vez en la sesión."] = "A matilha cumprimenta você na primeira vez que abre o Alfa na sessão.",
	["La mazmorra para mi nivel"] = "A masmorra para o meu nível",
	["La mazmorra para tu nivel, sus jefes, botín, misiones y consejos."] = "A masmorra para o seu nível, seus chefes, saque, missões e dicas.",
	["La mazmorra para tu nivel, sus misiones y cómo llegar."] = "A masmorra para o seu nível, as missões dela e como chegar.",
	["La mazmorra para tu nivel; con un nombre, esa mazmorra (también: progreso, ajustes)"] = "A masmorra para o seu nível; com um nome, essa masmorra (também: progreso, ajustes)",
	["La pesca de Alfa está apagada"] = "A pesca do Alfa está desativada",
	["La precisión es lo más importante: con dos armas fallas mucho sin ella."] = "A precisão é o mais importante: com duas armas você erra muito sem ela.",
	["La página de Bolsas; «abrir» abre tus bolsas y «banco» tu banco"] = "A página de Bolsas; “abrir” abre suas bolsas e “banco”, o seu banco",
	["La que te toca, con sus misiones y su botín."] = "A certa para você, com suas missões e seu saque.",
	["La recoges ahora"] = "Você pega agora",
	["La recomendada para ti y todas las demás"] = "O recomendado para você e todos os outros",
	["La recomendada para ti y todas las demás."] = "O recomendado para você e todos os outros.",
	["La ruta más rápida desde tu nivel, misión por misión."] = "A rota mais rápida a partir do seu nível, missão por missão.",
	["La ruta no trae tramos."] = "A rota não tem trechos.",
	["La ruta te lleva a %s. La flecha está apagada: enciéndela en Ajustes > Guía para verla."] = "A rota leva você até %s. A seta está desativada: ative em Opções > Guia para vê-la.",
	["La sacas de tu plan."] = "Você a tira do seu plano.",
	["La siguiente casilla cuesta %s y no te alcanza todavía."] = "O próximo espaço custa %s e ainda não dá para pagar.",
	["La subasta deja escanear todo cada 15 minutos. Falta %s."] = "O leilão permite escanear tudo a cada 15 minutos. Falta %s.",
	["La subasta no aceptó el escaneo. Intenta de nuevo más tarde."] = "O leilão não aceitou o escaneamento. Tente de novo mais tarde.",
	["La subasta no envió subastas. Intenta de nuevo más tarde."] = "O leilão não enviou nenhum leilão. Tente de novo mais tarde.",
	["La subasta no respondió. Puede que aún esté en espera: intenta en unos minutos."] = "O leilão não respondeu. Talvez ainda esteja em espera: tente em alguns minutos.",
	["La suma de lo que guardó Alfa de cada personaje (el tuyo, al día)."] = "A soma do que o Alfa guardou de cada personagem (o seu, atualizado).",
	["La tecla del botón de tu barra con esa habilidad, sobre el ícono."] = "A tecla do botão da sua barra com essa habilidade, sobre o ícone.",
	["La tecla del mapa abre este mapa"] = "A tecla do mapa abre este mapa",
	["La tecla que abre el mapa del juego (M) abre el de Alfa; en él, un botón te lleva al del juego. Apágalo y la tecla vuelve a abrir el del juego. También puedes darle una tecla propia en Opciones > Teclado > Alfa."] = "A tecla que abre o mapa do jogo (M) abre o do Alfa; nele, um botão leva você ao do jogo. Desative e a tecla volta a abrir o do jogo. Você também pode dar a ele uma tecla própria em Opções > Atalhos > Alfa.",
	["La tecla que usabas en tu otro addon de pesca (%s) ahora pesca con Alfa."] = "A tecla que você usava no seu outro addon de pesca (%s) agora pesca com o Alfa.",
	["La tomo otra vez"] = "Vou pegar de novo",
	["La trituradora tira a la gente: vuelve a llamar su atención rápido."] = "O retalhador derruba as pessoas: chame a atenção dele de novo rápido.",
	["La tuya tiene %d semanas: salen seguido."] = "A sua tem %d semanas: saem versões com frequência.",
	["La venta se detuvo: vendiste %d de %d."] = "A venda parou: você vendeu %d de %d.",
	["La ventana"] = "A janela",
	["Lanza bolas de fuego y fuego a su alrededor: interrúmpelo y, si peleas de lejos, aléjate."] = "Ele lança bolas de fogo e fogo ao redor: interrompa e, se você luta à distância, afaste-se.",
	["Lanza bombas de humo que aturden: sal del humo."] = "Ele joga bombas de fumaça que atordoam: saia da fumaça.",
	["Lanza con una tecla y recoge con la misma, con autobotín, sonido amplificado y doble clic."] = "Lance com uma tecla e recolha com a mesma, com saque automático, som amplificado e clique duplo.",
	["Lanza enredaderas que tumban a todos los que están cerca: si peleas de lejos, quédate lejos."] = "Ele lança trepadeiras que derrubam todos que estão perto: se você luta à distância, fique longe.",
	["Lanza fuego a su alrededor: si peleas de lejos, aléjate de él."] = "Ele lança fogo ao redor: se você luta à distância, afaste-se dele.",
	["Lanza hechizos de tierra y pone tótems: rompan los tótems primero."] = "Ele lança feitiços de terra e coloca totens: quebrem os totens primeiro.",
	["Lanza metal fundido: si no tanqueas, no te quedes pegado a él."] = "Ele lança metal derretido: se você não for o tanque, não fique colado nele.",
	["Lanza rayos y se puede curar: interrumpe sus hechizos."] = "Ela lança raios e pode se curar: interrompa os feitiços dela.",
	["Lanza ráfagas arcanas: interrúmpelo."] = "Ele lança rajadas arcanas: interrompa.",
	["Lanza sombras: interrúmpelo."] = "Ele lança sombras: interrompa.",
	["Lanza telarañas y una maldición: quita la maldición si puedes."] = "Ele lança teias e uma maldição: remova a maldição se puder.",
	["Lanza tormentas de arena que se mueven por la sala: no te pares en ellas."] = "Ele lança tempestades de areia que se movem pela sala: não fique parado nelas.",
	["Lanza tu hechizo más fuerte desde lejos y remata con los instantáneos."] = "Lance seu feitiço mais forte de longe e acabe com os instantâneos.",
	["Lanza tu hechizo más fuerte primero y remata con un choque."] = "Lance seu feitiço mais forte primeiro e acabe com um choque.",
	["Lanza una nube de veneno hacia adelante: gíralo lejos del grupo."] = "Ela solta uma nuvem de veneno para a frente: vire-a para longe do grupo.",
	["Lanza una red que deja quieto a un jugador: no es grave, sigue atacando."] = "Ele lança uma rede que deixa um jogador parado: não é grave, continue atacando.",
	["Lanza veneno a todos: quita el veneno si puedes."] = "Ele lança veneno em todos: remova o veneno se puder.",
	["Las cuentas"] = "As contas",
	["Las cuentas de prueba no pueden compartir: el juego no lo permite."] = "As contas de teste não podem compartilhar: o jogo não permite.",
	["Las dos se suben solas mientras matas y viajas, y lo que juntas se vende bien: oro para tu montura y tus habilidades."] = "As duas sobem sozinhas enquanto você mata e viaja, e o que você junta vende bem: ouro para sua montaria e suas habilidades.",
	["Las líneas que escribe Anunciar en el chat de tu grupo o banda."] = "As linhas que Anunciar escreve no chat do seu grupo ou raide.",
	["Las marca con una flecha."] = "As melhorias ganham uma seta.",
