	["Te llevo a %s"] = "Vou levar você a %s",
	["Te llevo a la mejor fuente. Recuerda que una montura pide nivel, equitación y oro."] = "Vou levar você à melhor fonte. Lembre que uma montaria pede nível, equitação e ouro.",
	["Te llevo a quien recibe cada una y recoges las que siguen."] = "Vou levar você a quem recebe cada uma, e você pega as que vêm depois.",
