	["Tienes %d puntos fuera de %s. Alfa nunca quita talentos: para seguir este build, reinicia tus talentos con tu entrenador de clase y Alfa te los vuelve a poner con un clic. O elige el build de la rama que ya llevas."] = "Você tem %d pontos fora de %s. O Alfa nunca remove talentos: para seguir esta build, reinicie seus talentos com o instrutor da sua classe e o Alfa os coloca de volta com um clique. Ou escolha a build do ramo que você já tem.",
	["Tienes %d puntos libres, pero los talentos que siguen en %s no existen en tu árbol (puede que cambiaran con un parche). Ponlos a mano en la ventana del juego o prueba otro estilo."] = "Você tem %d pontos livres, mas os próximos talentos de %s não existem na sua árvore (podem ter mudado num patch). Coloque-os à mão na janela do jogo ou tente outro estilo.",
	["Tienes %s precios de tus búsquedas. Para conocer todos, escanea en la casa de subastas."] = "Você tem %s preços das suas buscas. Para conhecer todos, escaneie na casa de leilões.",
	["Tienes 1 misión lista para entregar"] = "Você tem 1 missão pronta para entregar",
