	["Tu clase no tiene habilidades de reacción. Si quieres, Alfa te avisa cuando el juego hace brillar una de tus habilidades (en Avisos, abajo)."] = "Sua classe não tem habilidades de reação. Se quiser, o Alfa avisa quando o jogo faz uma das suas habilidades brilhar (em Avisos, abaixo).",
