	["Tu hermandad conectada"] = "Sua guilda conectada",
	["Tu historial"] = "Seu histórico",
	["Tu instalación está mezclada o incompleta (%s). Cierra el juego, borra todas las carpetas de Alfa en Interface/AddOns e instala Alfa de nuevo con la app de CurseForge o el zip más reciente (no \"Source code\")."] = "Sua instalação está misturada ou incompleta (%s). Feche o jogo, apague todas as pastas do Alfa em Interface/AddOns e instale o Alfa de novo com o app do CurseForge ou o zip mais recente (não \"Source code\").",
	["Tu libro no tiene hechizos para aliados"] = "Seu grimório não tem feitiços para aliados",
	["Tu lista de sonidos"] = "Sua lista de sons",
	["Tu lista de sonidos está vacía. Agrega uno con /alfa silenciar <número>."] = "Sua lista de sons está vazia. Adicione um com /alfa silenciar <número>.",
	["Tu lista de sonidos quedó vacía."] = "Sua lista de sons ficou vazia.",
	["Tu lista: síguelos con la flecha, compártelos con el grupo, cámbialos o bórralos."] = "Sua lista: siga-os com a seta, compartilhe com o grupo, mude ou apague.",
	["Tu manada"] = "Sua matilha",
	["Tu manada en el mapa: tu grupo y quienes usan Alfa y comparten. Síguelos con la flecha, invítalos y conoce al clan."] = "Sua matilha no mapa: seu grupo e quem usa o Alfa e compartilha. Siga-os com a seta, convide-os e conheça o clã.",
	["Tu manada está fuera del mapa"] = "Sua matilha está fora do mapa",
	["Tu manada te ve en el mapa y te puede seguir con la flecha. Lo apagas cuando quieras en la página de La Jauría."] = "Sua matilha vê você no mapa e pode seguir você com a seta. Desative quando quiser na página de La Jauría.",
	["Tu mapa"] = "Seu mapa",
	["Tu mapa del ratón está vacío: elige algo en una ranura primero."] = "O mapa do seu mouse está vazio: escolha algo para um espaço primeiro.",
	["Tu mascota"] = "Seu ajudante",
	["Tu mascota hace gran parte del trabajo y aguanta los golpes: la forma más fácil y segura de subir con cazador."] = "Seu ajudante faz boa parte do trabalho e aguenta os golpes: o jeito mais fácil e seguro de subir de nível com caçador.",
	["Tu munición"] = "Sua munição",
	["Tu nivel"] = "Seu nível",
	["Tu objetivo esquivó: Abrumar no se puede esquivar y pega fuerte. Necesita actitud de batalla."] = "Seu alvo se esquivou: Sobrepujar não pode ser esquivado e bate forte. Precisa da Postura de Batalha.",
	["Tu personaje deja de decir \"No tengo suficiente maná\", \"Eso todavía no está listo\" y parecidas. El texto rojo sigue."] = "Seu personagem para de dizer \"Mana insuficiente\", \"Ainda não está pronto\" e coisas parecidas. O texto vermelho continua.",
