	["Tus golpes alcanzan a un segundo enemigo: perfecto cuando se te juntan dos."] = "Seus golpes alcançam um segundo inimigo: perfeito quando dois se juntam contra você.",
	["Tus gritos llegan más lejos y duran más: ayudas a todo el grupo."] = "Seus brados alcançam mais longe e duram mais: você ajuda o grupo todo.",
